# =============================================================================
# NATIVE: GlobalMemoryStatusEx().ullTotalPhys == Node os.totalmem() (exact match)
# =============================================================================
if (-not ('SfNative' -as [type])) {
  Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class SfNative {
  [StructLayout(LayoutKind.Sequential)]
  public struct MEMORYSTATUSEX {
    public uint dwLength;
    public uint dwMemoryLoad;
    public ulong ullTotalPhys;
    public ulong ullAvailPhys;
    public ulong ullTotalPageFile;
    public ulong ullAvailPageFile;
    public ulong ullTotalVirtual;
    public ulong ullAvailVirtual;
    public ulong ullAvailExtendedVirtual;
  }
  [DllImport("kernel32.dll", SetLastError=true)]
  [return: MarshalAs(UnmanagedType.Bool)]
  public static extern bool GlobalMemoryStatusEx(ref MEMORYSTATUSEX lpBuffer);
  public static ulong TotalPhys() {
    MEMORYSTATUSEX m = new MEMORYSTATUSEX();
    m.dwLength = (uint)Marshal.SizeOf(typeof(MEMORYSTATUSEX));
    GlobalMemoryStatusEx(ref m);
    return m.ullTotalPhys;
  }
}
'@
}

# =============================================================================
# HWID - must be BYTE-IDENTICAL to the product's Node scheme:
#   raw = [ os.hostname(), os.platform(), os.arch(),
#           os.cpus()[0].model, String(os.totalmem()) ].join('|')
#   hwid = sha256(raw).hex.slice(0,16).toUpperCase()
# Each input is reproduced from the SAME OS source Node/libuv reads:
#   hostname   -> gethostname()               == [Net.Dns]::GetHostName()
#   platform   -> baked 'win32'
#   arch       -> baked 'x64' (installer arch; == Electron process.arch)
#   cpu model  -> registry ProcessorNameString (libuv reads this key, untrimmed)
#   totalmem   -> GlobalMemoryStatusEx ullTotalPhys (see SfNative above)
# =============================================================================
function Get-SfSha256Hex([string]$Raw) {
  $sha = [System.Security.Cryptography.SHA256]::Create()
  try { $bytes = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Raw)) }
  finally { $sha.Dispose() }
  return (-join ($bytes | ForEach-Object { $_.ToString('x2') }))   # lowercase hex
}

function Get-SfHwid {
  switch ($SF.HwidScheme) {
    # ---- Electron/Node os-based scheme (Nexus). BYTE-IDENTICAL to app/main.js:
    #   raw = [os.hostname(),os.platform(),os.arch(),os.cpus()[0].model,String(os.totalmem())].join('|')
    #   hwid = sha256(raw).hex.slice(0,16).toUpperCase()
    'node-os' {
      $hostname = [System.Net.Dns]::GetHostName()
      $cpu = ''
      try {
        $cpu = (Get-ItemProperty -Path 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -Name ProcessorNameString -ErrorAction Stop).ProcessorNameString
      } catch { $cpu = '' }
      $totalmem = [SfNative]::TotalPhys().ToString()
      $raw = @($hostname, $SF.Platform, $SF.Arch, $cpu, $totalmem) -join '|'
      return (Get-SfSha256Hex $raw).Substring(0, 16).ToUpper()
    }
    # ---- UDE PowerShell scheme. BYTE-IDENTICAL to Get-MachineFingerprint:
    #   sha256(UTF8("<MachineGuid>|<USERNAME>")) -> FULL lowercase hex (no slice, no upper)
    'ude-guid-user' {
      $mg = 'unknown-machine'
      try {
        $mg = (Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Cryptography' -Name MachineGuid -ErrorAction Stop).MachineGuid
      } catch { $mg = 'unknown-machine' }
      $user = if ($env:USERNAME) { $env:USERNAME } else { 'unknown-user' }
      return (Get-SfSha256Hex ("$mg|$user"))   # full 64-char lowercase hex
    }
    # ---- CastForge currently prepends a sorted MAC address (6 fields). Node's
    # os.networkInterfaces() enumeration/order is NOT reliably reproducible from
    # PowerShell, so we do NOT guess a fingerprint that would silently fail to
    # bind. CastForge's own APPROVED plan (docs\follow-up\PLAN-V2246-STABLE-HWID)
    # drops the MAC -> the scheme becomes 'node-os'. Until that ships, the stub
    # cannot mint a CastForge-matching HWID.
    'node-os-mac' {
      throw "CastForge HWID includes a MAC field that the stub cannot reproduce byte-identically. Execute the approved MAC-drop (PLAN-V2246 -> 'node-os') before building the CastForge stub."
    }
    default { throw "Unknown HwidScheme '$($SF.HwidScheme)'." }
  }
}

# =============================================================================
# HTTP helpers
# =============================================================================
function Invoke-SfPostJson([string]$Url, [hashtable]$Body) {
  $json = $Body | ConvertTo-Json -Compress
  return Invoke-RestMethod -Uri $Url -Method Post -ContentType 'application/json' -Body $json -TimeoutSec 20
}
function Invoke-SfGetJson([string]$Url) {
  return Invoke-RestMethod -Uri $Url -Method Get -TimeoutSec 20
}
function Invoke-SfDownload([string]$Url, [string]$OutFile, [hashtable]$Headers) {
  Invoke-WebRequest -Uri $Url -Headers $Headers -OutFile $OutFile -UseBasicParsing -TimeoutSec 120
}

function ConvertFrom-SfBase64Url([string]$s) {
  $s = $s.Replace('-', '+').Replace('_', '/')
  switch ($s.Length % 4) { 2 { $s += '==' } 3 { $s += '=' } }
  return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($s))
}

# Light, NON-SECURITY sanity check that the returned token is bound to THIS
# machine + THIS product, so we surface a clear error instead of installing a
# license the app would later reject. The real authenticity check is the
# worker's (server-side) and the app's (bundled public key). Parse failures do
# NOT block - the app is the source of truth.
function Test-SfTokenBinding([string]$Token, [string]$Hwid) {
  try {
    $parts = $Token.Trim().Split('.')
    if ($parts.Count -ge 3)      { $seg = $parts[1] }   # v2: header.payload.sig
    elseif ($parts.Count -eq 2)  { $seg = $parts[0] }   # v1 legacy: payload.sig
    else { return $false }
    $payload = ConvertFrom-SfBase64Url $seg | ConvertFrom-Json
    if ($payload.product -and ($payload.product -ne $SF.Product)) { return $false }
    $machine = if ($payload.machine) { $payload.machine } elseif ($payload.hwid) { $payload.hwid } else { $null }
    if ($machine -and (($machine.ToString().ToUpper()) -ne $Hwid)) { return $false }
    return $true
  } catch { return $true }
}

# =============================================================================
# GATED INSTALL: pull the manifest + installer from the token-gated feed, verify
# the published hash (sec6b.2), then run it. Returns the installer path.
# =============================================================================
# Compute a file hash in the algo+encoding the product publishes, so the compare
# is apples-to-apples: electron-updater publishes SHA-512/base64; the PS2EXE
# products publish SHA-256/hex.
function Get-SfFileHashEncoded([string]$Path) {
  $algo = if ($SF.HashField -eq 'sha256') { [System.Security.Cryptography.SHA256]::Create() }
          else                            { [System.Security.Cryptography.SHA512]::Create() }
  try {
    $fb = [System.IO.File]::ReadAllBytes($Path)
    $raw = $algo.ComputeHash($fb)
  } finally { $algo.Dispose() }
  if ($SF.HashEncoding -eq 'hex') { return (-join ($raw | ForEach-Object { $_.ToString('x2') })) }
  return [Convert]::ToBase64String($raw)
}

function Get-SfInstallerVerified([string]$Token) {
  $base    = "https://$($SF.LicenseDomain)/updates/$($SF.Product)"
  $headers = @{ Authorization = "Bearer $Token" }

  # 1) manifest (gated) -> name the installer file + its published hash. Two
  #    shapes, chosen by product: electron-updater 'latest.yml' (path:/sha512:)
  #    or the uniform PS2EXE 'latest.json' ({ file, sha256 }).
  $manPath = Join-Path $env:TEMP "$($SF.Product)-$($SF.FeedManifest)"
  Invoke-SfDownload "$base/$([uri]::EscapeDataString($SF.FeedManifest))" $manPath $headers
  $manRaw = Get-Content -Path $manPath -Raw

  $file = ''; $hash = ''
  if ($SF.ManifestKind -eq 'ude-json') {
    $m = $manRaw | ConvertFrom-Json
    $file = if ($m.file) { $m.file } elseif ($m.path) { $m.path } else { '' }
    $hash = if ($m.sha256) { $m.sha256 } elseif ($m.hash) { $m.hash } else { '' }
  } else {
    # electron-updater latest.yml
    $file = [regex]::Match($manRaw, '(?m)^path:\s*(\S.*?)\s*$').Groups[1].Value
    $hash = [regex]::Match($manRaw, '(?m)^sha512:\s*(\S+)\s*$').Groups[1].Value
  }
  if (-not $file) { throw "Feed manifest did not name an installer." }
  if (-not $hash) { throw "Feed manifest published no $($SF.HashField) hash to verify against." }

  # 2) installer (Bearer-gated; worker already verified the license to serve it)
  $instPath = Join-Path $env:TEMP $file
  Invoke-SfDownload "$base/$([uri]::EscapeDataString($file))" $instPath $headers

  # 3) integrity: computed hash (product's algo+encoding) must equal the published one
  $calc = Get-SfFileHashEncoded $instPath
  $ok = if ($SF.HashEncoding -eq 'hex') { $calc -ieq $hash } else { $calc -ceq $hash }
  if (-not $ok) {
    try { Remove-Item $instPath -Force -ErrorAction SilentlyContinue } catch {}
    throw "Installer integrity check FAILED (published hash mismatch). Nothing was run."
  }
  return $instPath
}

function Invoke-SfInstaller([string]$InstallerPath) {
  if ($SF.InstallerArgs) {
    Start-Process -FilePath $InstallerPath -ArgumentList $SF.InstallerArgs -Wait
  } else {
    Start-Process -FilePath $InstallerPath -Wait
  }
}

# Write license.json exactly in the shape the app reads: { key, hwid, activatedAt }.
# UTF-8 WITHOUT BOM - the app does JSON.parse(readFileSync(..,'utf8')); a BOM
# would break that parse.
function Write-SfLicense([string]$Token, [string]$Hwid) {
  # UDE (PowerShell app) reads its license from HKCU:\SOFTWARE\UDE, not a file.
  # The EXACT value names are pinned against the engine's license-read code when
  # the UDE worker/activation is built (task: UDE gated proxy) - until then this
  # path refuses rather than write guessed keys that would fail to activate.
  if ($SF.ActivationTarget -eq 'ude-registry') {
    throw "UDE registry activation is not wired yet (pending the UDE worker/activation task). The stub will not write guessed registry keys."
  }
  # Electron products: license.json in the app's userData dir.
  # Accept both PowerShell-style ($env:APPDATA, already expanded at parse) and
  # %VAR%-style paths from product.config.
  $dir = [System.Environment]::ExpandEnvironmentVariables($SF.LicenseDir)
  if (-not (Test-Path $dir)) {
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
  }
  $rec = [ordered]@{
    key         = $Token.Trim()
    hwid        = $Hwid
    activatedAt = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ss.fffZ")
  }
  $json = ($rec | ConvertTo-Json)
  $path = Join-Path $dir $SF.LicenseFile
  [System.IO.File]::WriteAllText($path, $json, (New-Object System.Text.UTF8Encoding($false)))
}

# request-id persistence so a relaunch resumes a still-pending request
function Get-SfRequestStatePath { Join-Path $env:TEMP "$($SF.Product)-stub-request.json" }
function Save-SfRequestState([string]$RequestId) {
  $rec  = @{ requestId = $RequestId; at = (Get-Date).ToUniversalTime().ToString('o') } | ConvertTo-Json
  [System.IO.File]::WriteAllText((Get-SfRequestStatePath), $rec, (New-Object System.Text.UTF8Encoding($false)))
}
function Read-SfRequestState {
  try { return Get-Content -Path (Get-SfRequestStatePath) -Raw | ConvertFrom-Json } catch { return $null }
}
function Clear-SfRequestState { try { Remove-Item (Get-SfRequestStatePath) -Force -ErrorAction SilentlyContinue } catch {} }

