$lblStatus = New-Object System.Windows.Forms.Label
$lblStatus.Location = New-Object System.Drawing.Point(20, 278)
$lblStatus.Size = New-Object System.Drawing.Size(400, 44)
$lblStatus.Text = 'Fill in your details and request a license. Approval releases the download.'
$form.Controls.Add($lblStatus)

function Set-SfStatus([string]$msg) { $lblStatus.Text = $msg; $lblStatus.Refresh() }

function Stop-SfPoll {
  if ($script:PollTimer) { $script:PollTimer.Stop(); $script:PollTimer.Dispose(); $script:PollTimer = $null }
}

# ---- APPROVED: run the whole gated install, then close ----------------------
function Complete-SfApproved([string]$Token) {
  Stop-SfPoll
  $btnRequest.Enabled = $false
  try {
    if (-not (Test-SfTokenBinding $Token $script:Hwid)) {
      Set-SfStatus "The approved license does not match this device/product. Contact support."
      return
    }
    Set-SfStatus "Approved. Downloading and verifying the installer..."
    $installer = Get-SfInstallerVerified $Token
    Set-SfStatus "Verified. Running the installer..."
    Invoke-SfInstaller $installer
    Write-SfLicense $Token $script:Hwid
    Clear-SfRequestState
    Set-SfStatus "Done. $($SF.DisplayName) is installed and pre-activated."
    [System.Windows.Forms.MessageBox]::Show("$($SF.DisplayName) is installed and activated. You can launch it now.", 'Steadfast', 'OK', 'Information') | Out-Null
    $form.Close()
  } catch {
    Set-SfStatus "Install failed: $($_.Exception.Message)"
    $btnRequest.Enabled = $true
  }
}

# ---- poll tick --------------------------------------------------------------
function Invoke-SfPollTick {
  if (-not $script:RequestId) { Stop-SfPoll; return }
  if (((Get-Date) - $script:PollStarted).TotalMinutes -ge $SF.PollTimeoutMin) {
    Stop-SfPoll
    Set-SfStatus "No response yet. Reopen this installer later to resume - your request is saved."
    $btnRequest.Enabled = $true
    return
  }
  try {
    $r = Invoke-SfGetJson "https://$($SF.LicenseDomain)$($SF.ApiPrefix)/poll/$([uri]::EscapeDataString($script:RequestId))"
    if ($r -and $r.status) {
      switch ($r.status) {
        'approved' {
          if ($r.token) { Complete-SfApproved ([string]$r.token) }
          else { Set-SfStatus "Approved - waiting for the signed token..." }
        }
        'rejected' {
          Stop-SfPoll
          $reason = if ($r.rejectedReason) { $r.rejectedReason } else { 'no reason given' }
          Set-SfStatus "Request declined: $reason. Nothing was downloaded."
          Clear-SfRequestState
          $btnRequest.Enabled = $true
        }
        default { Set-SfStatus "Waiting for operator approval... (device $($script:Hwid))" }
      }
    }
  } catch {
    Set-SfStatus "Still waiting (server unreachable, will retry): $($_.Exception.Message)"
  }
}

function Start-SfPoll {
  Stop-SfPoll
  $script:PollStarted = Get-Date
  $script:PollTimer = New-Object System.Windows.Forms.Timer
  $script:PollTimer.Interval = [int]($SF.PollSeconds * 1000)
  $script:PollTimer.Add_Tick({ Invoke-SfPollTick })
  $script:PollTimer.Start()
  Invoke-SfPollTick
}

# ---- request button ---------------------------------------------------------
$btnRequest.Add_Click({
  $name  = $txtName.Text.Trim()
  $email = $txtEmail.Text.Trim()
  if (-not $name -or -not $email) { Set-SfStatus 'Please enter your name and email.'; return }
  if ($email -notmatch '^[^@\s]+@[^@\s]+\.[^@\s]+$') { Set-SfStatus 'Please enter a valid email.'; return }
  $btnRequest.Enabled = $false
  Set-SfStatus 'Sending request...'
  try {
    $body = @{ name = $name; email = $email; hwid = $script:Hwid; appVersion = 'stub' }
    if ($txtCompany.Text.Trim()) { $body.company = $txtCompany.Text.Trim() }
    $resp = Invoke-SfPostJson "https://$($SF.LicenseDomain)$($SF.ApiPrefix)/request" $body
    if ($resp -and $resp.requestId) {
      $script:RequestId = [string]$resp.requestId
      Save-SfRequestState $script:RequestId
      Set-SfStatus 'Request sent. Waiting for operator approval...'
      Start-SfPoll
    } else {
      $err = if ($resp -and $resp.error) { $resp.error } else { 'unknown error' }
      Set-SfStatus "Request failed: $err"
      $btnRequest.Enabled = $true
    }
  } catch {
    Set-SfStatus "Could not reach the license server: $($_.Exception.Message)"
    $btnRequest.Enabled = $true
  }
})

# ---- resume a still-pending request on launch -------------------------------
$prev = Read-SfRequestState
if ($prev -and $prev.requestId) {
  $script:RequestId = [string]$prev.requestId
  Set-SfStatus 'Resuming a pending request. Waiting for approval...'
  $btnRequest.Enabled = $false
  Start-SfPoll
}

$form.Add_FormClosed({ Stop-SfPoll })
[void]$form.ShowDialog()
